-- ============================================================================
-- KAMELA - FINAL DATABASE RESET + DEMO SEED
-- Final consolidated schema after Security/Foundation Phase 1-6
-- Generated: 2026-09-21
--
-- THIS FILE IS DESTRUCTIVE.
-- It drops and recreates every KAMELA application table in database `pos_ci4`.
-- Use for fresh clone, demo environment, classroom device, or intentional reset.
-- BACK UP any important database before importing.
--
-- Included foundation:
--   * Base POS + purchasing + stock mutation
--   * Phase 2 authorization/data-integrity DB constraints
--   * Phase 3 audit_logs
--   * Phase 5 controlled stock_opname tables
--   * Phase 4 backup/recovery and Phase 6 production hardening are application-level
--     features and therefore require no extra database tables.
--
-- Demo accounts after import:
--   Admin : admin / admin123
--   Kasir : kasir / kasir123
-- ============================================================================

CREATE DATABASE IF NOT EXISTS `pos_ci4`
  CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `pos_ci4`;

SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '+07:00';
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------------------------------------------------------
-- Clean reset: drop final-schema tables first so legacy columns/constraints
-- cannot survive from older versions of the project.
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `audit_logs`;
DROP TABLE IF EXISTS `stock_opname_detail`;
DROP TABLE IF EXISTS `stock_opname`;
DROP TABLE IF EXISTS `mutasi_stok`;
DROP TABLE IF EXISTS `detail_pembelian`;
DROP TABLE IF EXISTS `pembelian`;
DROP TABLE IF EXISTS `demo_payments`;
DROP TABLE IF EXISTS `detail_penjualan`;
DROP TABLE IF EXISTS `penjualan`;
DROP TABLE IF EXISTS `barang`;
DROP TABLE IF EXISTS `kategori`;
DROP TABLE IF EXISTS `customer`;
DROP TABLE IF EXISTS `supplier`;
DROP TABLE IF EXISTS `users`;

-- ----------------------------------------------------------------------------
-- Core master tables
-- ----------------------------------------------------------------------------
CREATE TABLE `users` (
  `id_user` INT NOT NULL AUTO_INCREMENT,
  `username` VARCHAR(50) NOT NULL,
  `password` VARCHAR(255) NOT NULL,
  `nama_lengkap` VARCHAR(100) NOT NULL,
  `role` ENUM('admin','kasir') NOT NULL DEFAULT 'kasir',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_user`),
  UNIQUE KEY `uk_users_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `kategori` (
  `id_kategori` INT NOT NULL AUTO_INCREMENT,
  `nama_kategori` VARCHAR(100) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_kategori`),
  UNIQUE KEY `uk_kategori_nama` (`nama_kategori`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `customer` (
  `id_customer` INT NOT NULL AUTO_INCREMENT,
  `nama_customer` VARCHAR(100) NOT NULL,
  `no_telp` VARCHAR(20) DEFAULT NULL,
  `alamat` TEXT DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_customer`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `supplier` (
  `id_supplier` INT NOT NULL AUTO_INCREMENT,
  `nama_supplier` VARCHAR(100) NOT NULL,
  `no_telp` VARCHAR(20) DEFAULT NULL,
  `alamat` TEXT DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_supplier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `barang` (
  `id_barang` INT NOT NULL AUTO_INCREMENT,
  `id_kategori` INT NOT NULL,
  `kode_barang` VARCHAR(50) NOT NULL,
  `nama_barang` VARCHAR(150) NOT NULL,
  `harga_beli` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `harga_jual` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `stok` INT NOT NULL DEFAULT 0,
  `satuan` VARCHAR(30) NOT NULL DEFAULT 'pcs',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_barang`),
  UNIQUE KEY `uk_barang_kode` (`kode_barang`),
  KEY `idx_barang_kategori` (`id_kategori`),
  CONSTRAINT `fk_barang_kategori`
    FOREIGN KEY (`id_kategori`) REFERENCES `kategori` (`id_kategori`)
    ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------------------------------------------------------
-- Sales
-- Phase 2 keeps customer history intact with ON DELETE RESTRICT.
-- ----------------------------------------------------------------------------
CREATE TABLE `penjualan` (
  `id_penjualan` INT NOT NULL AUTO_INCREMENT,
  `no_transaksi` VARCHAR(30) NOT NULL,
  `tanggal` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_customer` INT DEFAULT NULL,
  `id_user` INT NOT NULL,
  `total` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `metode_pembayaran` VARCHAR(30) NOT NULL DEFAULT 'Tunai',
  `bayar` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `kembalian` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`id_penjualan`),
  UNIQUE KEY `uk_penjualan_no_transaksi` (`no_transaksi`),
  KEY `idx_penjualan_customer` (`id_customer`),
  KEY `idx_penjualan_user` (`id_user`),
  KEY `idx_penjualan_tanggal` (`tanggal`),
  CONSTRAINT `fk_penjualan_customer`
    FOREIGN KEY (`id_customer`) REFERENCES `customer` (`id_customer`)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_penjualan_user`
    FOREIGN KEY (`id_user`) REFERENCES `users` (`id_user`)
    ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `detail_penjualan` (
  `id_detail` INT NOT NULL AUTO_INCREMENT,
  `id_penjualan` INT NOT NULL,
  `id_barang` INT NOT NULL,
  `qty` INT NOT NULL,
  `harga` DECIMAL(15,2) NOT NULL,
  `harga_modal` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `subtotal` DECIMAL(15,2) NOT NULL,
  PRIMARY KEY (`id_detail`),
  KEY `idx_detail_penjualan_header` (`id_penjualan`),
  KEY `idx_detail_penjualan_barang` (`id_barang`),
  CONSTRAINT `fk_detail_penjualan_header`
    FOREIGN KEY (`id_penjualan`) REFERENCES `penjualan` (`id_penjualan`)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_detail_penjualan_barang`
    FOREIGN KEY (`id_barang`) REFERENCES `barang` (`id_barang`)
    ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------------------------------------------------------
-- Purchasing / restock
-- ----------------------------------------------------------------------------
CREATE TABLE `pembelian` (
  `id_pembelian` INT NOT NULL AUTO_INCREMENT,
  `no_pembelian` VARCHAR(30) NOT NULL,
  `tanggal` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_supplier` INT NOT NULL,
  `id_user` INT NOT NULL,
  `total` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `catatan` VARCHAR(255) DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_pembelian`),
  UNIQUE KEY `uk_pembelian_no` (`no_pembelian`),
  KEY `idx_pembelian_supplier` (`id_supplier`),
  KEY `idx_pembelian_user` (`id_user`),
  KEY `idx_pembelian_tanggal` (`tanggal`),
  CONSTRAINT `fk_pembelian_supplier`
    FOREIGN KEY (`id_supplier`) REFERENCES `supplier` (`id_supplier`)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pembelian_user`
    FOREIGN KEY (`id_user`) REFERENCES `users` (`id_user`)
    ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `detail_pembelian` (
  `id_detail_pembelian` INT NOT NULL AUTO_INCREMENT,
  `id_pembelian` INT NOT NULL,
  `id_barang` INT NOT NULL,
  `qty` INT NOT NULL,
  `harga_beli` DECIMAL(15,2) NOT NULL,
  `subtotal` DECIMAL(15,2) NOT NULL,
  PRIMARY KEY (`id_detail_pembelian`),
  KEY `idx_detail_pembelian_header` (`id_pembelian`),
  KEY `idx_detail_pembelian_barang` (`id_barang`),
  CONSTRAINT `fk_detail_pembelian_header`
    FOREIGN KEY (`id_pembelian`) REFERENCES `pembelian` (`id_pembelian`)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_detail_pembelian_barang`
    FOREIGN KEY (`id_barang`) REFERENCES `barang` (`id_barang`)
    ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `mutasi_stok` (
  `id_mutasi` INT NOT NULL AUTO_INCREMENT,
  `id_barang` INT NOT NULL,
  `id_user` INT NOT NULL,
  `tipe` ENUM('MASUK','KELUAR','PENYESUAIAN') NOT NULL,
  `qty` INT NOT NULL,
  `stok_sebelum` INT NOT NULL,
  `stok_sesudah` INT NOT NULL,
  `referensi_tipe` VARCHAR(30) DEFAULT NULL,
  `referensi_id` INT DEFAULT NULL,
  `keterangan` VARCHAR(255) DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_mutasi`),
  KEY `idx_mutasi_barang` (`id_barang`),
  KEY `idx_mutasi_user` (`id_user`),
  KEY `idx_mutasi_created` (`created_at`),
  CONSTRAINT `fk_mutasi_barang`
    FOREIGN KEY (`id_barang`) REFERENCES `barang` (`id_barang`)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_mutasi_user`
    FOREIGN KEY (`id_user`) REFERENCES `users` (`id_user`)
    ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------------------------------------------------------
-- Phase 3 - audit trail / accountability
-- ----------------------------------------------------------------------------
-- KAMELA Phase 7 - Dynamic QR Payment Simulation
-- Run ONCE on an existing KAMELA database.
CREATE TABLE IF NOT EXISTS `demo_payments` (
  `id_demo_payment` BIGINT NOT NULL AUTO_INCREMENT,
  `token` CHAR(64) NOT NULL,
  `method` ENUM('QRIS','TRANSFER') NOT NULL DEFAULT 'QRIS',
  `payment_reference` VARCHAR(32) DEFAULT NULL,
  `id_user` INT NOT NULL,
  `id_customer` INT DEFAULT NULL,
  `amount` DECIMAL(15,2) NOT NULL,
  `payload` LONGTEXT NOT NULL,
  `status` ENUM('PENDING','PAID','EXPIRED','FAILED','CANCELLED') NOT NULL DEFAULT 'PENDING',
  `expires_at` DATETIME NOT NULL,
  `paid_at` DATETIME DEFAULT NULL,
  `cancelled_at` DATETIME DEFAULT NULL,
  `id_penjualan` INT DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_demo_payment`),
  UNIQUE KEY `uk_demo_payment_token` (`token`),
  UNIQUE KEY `uk_demo_payment_reference` (`payment_reference`),
  KEY `idx_demo_payment_status` (`status`),
  KEY `idx_demo_payment_method` (`method`),
  KEY `idx_demo_payment_user` (`id_user`),
  KEY `idx_demo_payment_customer` (`id_customer`),
  KEY `idx_demo_payment_penjualan` (`id_penjualan`),
  CONSTRAINT `fk_demo_payment_user` FOREIGN KEY (`id_user`) REFERENCES `users` (`id_user`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_demo_payment_customer` FOREIGN KEY (`id_customer`) REFERENCES `customer` (`id_customer`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_demo_payment_penjualan` FOREIGN KEY (`id_penjualan`) REFERENCES `penjualan` (`id_penjualan`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `audit_logs` (
  `id_audit` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_user` INT NULL,
  `actor_username` VARCHAR(50) NULL,
  `actor_name` VARCHAR(100) NULL,
  `actor_role` VARCHAR(30) NULL,
  `action` VARCHAR(50) NOT NULL,
  `entity_type` VARCHAR(50) NOT NULL,
  `entity_id` VARCHAR(64) NULL,
  `entity_label` VARCHAR(150) NULL,
  `description` VARCHAR(255) NULL,
  `before_data` LONGTEXT NULL,
  `after_data` LONGTEXT NULL,
  `status` ENUM('SUCCESS','FAILED','BLOCKED') NOT NULL DEFAULT 'SUCCESS',
  `ip_address` VARCHAR(45) NULL,
  `user_agent` VARCHAR(255) NULL,
  `http_method` VARCHAR(10) NULL,
  `request_uri` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_audit`),
  KEY `idx_audit_created_at` (`created_at`),
  KEY `idx_audit_user` (`id_user`),
  KEY `idx_audit_action` (`action`),
  KEY `idx_audit_entity` (`entity_type`,`entity_id`),
  KEY `idx_audit_status` (`status`),
  CONSTRAINT `fk_audit_user`
    FOREIGN KEY (`id_user`) REFERENCES `users` (`id_user`)
    ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------------------------------------------------------
-- Phase 5 - controlled stock opname
-- ----------------------------------------------------------------------------
CREATE TABLE `stock_opname` (
  `id_opname` INT NOT NULL AUTO_INCREMENT,
  `no_opname` VARCHAR(40) NOT NULL,
  `tanggal` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_user` INT NOT NULL,
  `status` ENUM('DRAFT','FINALIZED','CANCELLED') NOT NULL DEFAULT 'DRAFT',
  `catatan` VARCHAR(255) NULL,
  `active_guard` TINYINT NULL DEFAULT 1,
  `finalized_by` INT NULL,
  `finalized_at` DATETIME NULL,
  `cancelled_by` INT NULL,
  `cancelled_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_opname`),
  UNIQUE KEY `uk_stock_opname_no` (`no_opname`),
  UNIQUE KEY `uk_stock_opname_single_draft` (`active_guard`),
  KEY `idx_stock_opname_status` (`status`),
  KEY `idx_stock_opname_user` (`id_user`),
  CONSTRAINT `fk_stock_opname_user`
    FOREIGN KEY (`id_user`) REFERENCES `users` (`id_user`)
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_stock_opname_finalized_by`
    FOREIGN KEY (`finalized_by`) REFERENCES `users` (`id_user`)
    ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_stock_opname_cancelled_by`
    FOREIGN KEY (`cancelled_by`) REFERENCES `users` (`id_user`)
    ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `stock_opname_detail` (
  `id_detail_opname` INT NOT NULL AUTO_INCREMENT,
  `id_opname` INT NOT NULL,
  `id_barang` INT NOT NULL,
  `stok_sistem` INT NOT NULL,
  `stok_fisik` INT NULL,
  `selisih` INT NULL,
  PRIMARY KEY (`id_detail_opname`),
  UNIQUE KEY `uk_opname_barang` (`id_opname`,`id_barang`),
  KEY `idx_opname_detail_barang` (`id_barang`),
  CONSTRAINT `fk_opname_detail_header`
    FOREIGN KEY (`id_opname`) REFERENCES `stock_opname` (`id_opname`)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_opname_detail_barang`
    FOREIGN KEY (`id_barang`) REFERENCES `barang` (`id_barang`)
    ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

